/* eslint-disable solid/reactivity */

import { createMemo, type Component as ParentComponent } from "solid-js";

import { ComponentRegistry } from "#core/ui-next/services/component-registry.js";
import { ViewExperience } from "#core/ui-next/services/view-experience.js";

import { Activatable, ActivatableProps } from "./activatable";

export enum RadioButtonSize {
	SMALL = "small",
	LARGE = "large",
	STANDARD = "standard",
}

export type RadioButtonProps = {
	isChecked?: boolean;
	size?: RadioButtonSize;
	highRes?: boolean;
} & ActivatableProps;

const RadioButtonComponent: ParentComponent<RadioButtonProps> = (props) => {
	props.audio ??= {};
	props.audio.group = "radio-button";
	const isMobile = createMemo(() => ViewExperience() == UIViewExperience.Mobile);
	const isHighRes = createMemo(() => props.highRes == true);

	const sizeConfig = {
		[RadioButtonSize.SMALL]: {
			button: "size-6",
			ball: "img-radio-button-ball-sm",
		},
		[RadioButtonSize.LARGE]: {
			button: "size-10",
			ball: "img-radio-button-ball-lg",
		},
		[RadioButtonSize.STANDARD]: {
			button: "size-8",
			ball: "img-radio-button-ball",
		},
	};

	const sizeStyles = createMemo(() => {
		const mode = isMobile() ? RadioButtonSize.LARGE : (props.size ?? RadioButtonSize.STANDARD);

		return sizeConfig[mode];
	});

	return (
		<Activatable
			{...props}
			class={`flex flex-row group justify-center items-center ${props.class ?? ""}`}
			name="RadioButton"
		>
			<div
				class={
					"img-radio-button cursor-pointer pointer-events-auto relative flex justify-center items-center " +
					sizeStyles().button
				}
				classList={{
					"high-res": isHighRes(),
				}}
			>
				<div
					class={sizeStyles().ball}
					classList={{
						"opacity-0": !props.isChecked,
						"high-res": isHighRes(),
					}}
				/>
				<div
					class="absolute inset-0 opacity-0 group-hover\:opacity-100 group-focus\:opacity-100 group-pressed\:opacity-100 transition-opacity"
					classList={{
						"img-radio-button-focus": !props.isChecked,
						"img-radio-button-on-focus": props.isChecked,
						"high-res": isHighRes(),
					}}
				/>
			</div>
			<div class="flex flex-row justify-center items-center">{props.children}</div>
		</Activatable>
	);
};

/**
 * A radio button
 * Shows a toggleable state. Can be used as a pip in other components.
 * ```tsx
 * // Example: Toggleable pip
 * const [isToggled, setIsToggled] = createSignal(false);
 * ...
 * <RadioButton isChecked={isToggled()} onActivate={() => setIsToggled((toggled) => !toggled)} />
 * ```
 * Default implementation: {@link PanelComponent}
 * @param {PanelProps} props See {@link PanelProps} for a full list of properties
 *
 * Commonly Used Properties:
 * @param {string} props.name The name of the panel. This is used for various tracking contexts like focus.
 */
export const RadioButton = ComponentRegistry.register({
	name: "RadioButton",
	createInstance: RadioButtonComponent,
	images: [
		"blp:base_radio-bg",
		"blp:base_radio-ball",
		"blp:base_radio-bg-focus",
		"blp:base_radio-bg-on-focus",
		"blp:base_radio-bg_highRes",
		"blp:base_radio-ball_highRes",
		"blp:base_radio-bg-focus_highRes",
		"blp:base_radio-bg-on-focus_highRes",
	],
});
